const config = $input.first().json;
const span = 14 * 24 * 60 * 60 * 1000;
function parseDay(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) throw new Error('Reporting dates must use YYYY-MM-DD.');
  const time = Date.parse(value + 'T00:00:00Z');
  if (!Number.isFinite(time) || new Date(time).toISOString().slice(0, 10) !== value) throw new Error('Invalid reporting date.');
  return time;
}
const anchor = parseDay(config.firstPeriodEnd);
const now = Date.now();
const scheduled = $('Sunday schedule').isExecuted;
const today = Date.parse(new Date(now).toISOString().slice(0, 10) + 'T00:00:00Z');
if (scheduled && (today < anchor || (today - anchor) % span !== 0)) return [];
const end = scheduled
  ? today
  : config.overridePeriodEnd
    ? parseDay(config.overridePeriodEnd)
    : anchor + Math.floor((now - anchor) / span) * span;
if (end < anchor || end > now || (end - anchor) % span !== 0) throw new Error('Use a completed reporting period aligned with firstPeriodEnd.');
if (config.planeBaseUrl !== 'https://plane.stevensweb.org' || config.websiteUrl !== 'https://eagleye.stevensweb.org') throw new Error('Review destination URLs before changing this workflow.');
const periodStart = new Date(end - span).toISOString().slice(0, 10);
const periodEnd = new Date(end).toISOString().slice(0, 10);
if (!Array.isArray(config.projects) || !config.projects.length) throw new Error('At least one Plane project is required.');
if (config.projects.some(project => !/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(project.id))) {
  throw new Error('Copy the four Plane project UUIDs into Project configuration.');
}
return config.projects.map(project => ({ json: {
  ...config, project, periodStart, periodEnd,
  workItemsUrl: config.planeBaseUrl + '/api/v1/workspaces/' + encodeURIComponent(config.workspaceSlug) + '/projects/' + encodeURIComponent(project.id) + '/work-items/'
}}));

const config = $('Reporting period').first().json;
const projects = new Map(config.projects.map(project => [project.id, project]));
const workItems = new Map();
for (const item of $input.all()) {
  const page = item.json;
  if (!Array.isArray(page.results)) throw new Error('Unexpected Plane work-item response. Check the API version and pagination configuration.');
  for (const work of page.results) {
    const projectId = typeof work.project === 'object' && work.project ? work.project.id : work.project;
    const project = projects.get(projectId);
    if (!project || typeof work.id !== 'string') throw new Error('A work item has no recognized project or ID.');
    const sensitive = /password|credential|secret|api[ -]?key|access[ -]?token/i.test(work.name || '');
    workItems.set(work.id, { id: work.id, name: sensitive ? '[Private access task]' : String(work.name || 'Untitled work item'), sensitive,
      projectId, projectName: project.name, identifier: project.identifier + '-' + work.sequence_id,
      activityUrl: config.planeBaseUrl + '/api/v1/workspaces/' + encodeURIComponent(config.workspaceSlug) + '/projects/' + encodeURIComponent(projectId) + '/work-items/' + encodeURIComponent(work.id) + '/activities/' });
  }
}
if (!workItems.size) return [{ json: { skipActivity: true } }];
return [...workItems.values()].map(work => ({ json: { ...work, skipActivity: false } }));

const period = $('Reporting period').first().json;
const workItems = new Map($('Prepare work items').all().filter(item => !item.json.skipActivity).map(item => [item.json.id, item.json]));
const start = Date.parse(period.periodStart + 'T00:00:00Z');
const end = Date.parse(period.periodEnd + 'T00:00:00Z');
const activityMap = new Map();
const contextMap = new Map();
const modelActivityMap = new Map();
const modelFields = new Set(['state', 'status', 'start_date', 'target_date', 'priority']);
const valueText = value => value === null || value === undefined || value === '' ? null : typeof value === 'string' ? value : JSON.stringify(value);
for (const item of $input.all()) {
  if (item.json.skipActivity) continue;
  const page = item.json;
  if (!Array.isArray(page.results)) throw new Error('Unexpected Plane activity response; do not publish incomplete evidence.');
  for (const event of page.results) {
    const time = Date.parse(event.created_at);
    if (!Number.isFinite(time)) throw new Error('An activity has no valid timestamp.');
    if (time < start || time >= end) continue;
    const reference = event.work_item ?? event.issue;
    const workId = typeof reference === 'object' && reference ? reference.id : reference;
    const work = workItems.get(workId);
    if (!work || typeof event.id !== 'string') throw new Error('An activity has no recognized work item or ID.');
    const field = valueText(event.field);
    // Credentials, descriptions, and comment text are not sent to the model or public site.
    const omitValues = work.sensitive || /description|comment|password|secret|token|credential/i.test(field || '');
    const activity = {
      id: event.id, workItemId: work.identifier, createdAt: new Date(time).toISOString(),
      field, verb: valueText(event.verb),
      oldValue: omitValues ? null : valueText(event.old_value),
      newValue: omitValues ? null : valueText(event.new_value),
      url: period.planeBaseUrl + '/' + period.workspaceSlug + '/browse/' + encodeURIComponent(work.identifier) + '/'
    };
    for (const key of ['oldValue', 'newValue']) if (activity[key] && activity[key].length > 8000) throw new Error('Plane evidence exceeds the website field limit. Review before publishing.');
    if ((field && field.length > 160) || (activity.verb && activity.verb.length > 160)) throw new Error('Plane activity metadata exceeds the website limit.');
    activityMap.set(event.id, activity);
    if (!work.sensitive && (modelFields.has(field) || activity.verb === 'created')) {
      const { workItemId, createdAt, verb, oldValue, newValue } = activity;
      const includeValues = modelFields.has(field);
      modelActivityMap.set(event.id, {
        workItemId, createdAt, verb, field,
        oldValue: includeValues ? oldValue : null,
        newValue: includeValues ? newValue : null,
      });
      contextMap.set(workItemId, { workItemId, title: work.name, project: work.projectName });
    }
  }
}
const activities = [...activityMap.values()].sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.id.localeCompare(b.id));
if (activities.length > 1000) throw new Error('More than 1000 activity records. Increase backend capacity or review evidence; do not silently truncate.');
const context = [...contextMap.values()];
const modelActivities = [...modelActivityMap.values()];
const evidence = JSON.stringify({ context, activities: modelActivities });
if (evidence.length > 120000) throw new Error('Too much evidence for one model request. Add a chunked summarization stage before continuing.');
return [{ json: { periodStart: period.periodStart, periodEnd: period.periodEnd, websiteUrl: period.websiteUrl,
  publishEnabled: period.publishEnabled === true, activities, context, modelActivities, evidenceCount: activities.length } }];

const collected = $('Collect Plane activity').first().json;
let content = $input.first().json;
content = content.output ?? content.text ?? content;
if (typeof content === 'string') content = JSON.parse(content);
for (const [key, max] of [['title', 140], ['summary', 600], ['body', 30000]]) {
  if (typeof content[key] !== 'string' || !content[key].trim() || content[key].length > max) throw new Error('Generated ' + key + ' is missing or exceeds the website limit.');
}
const payload = { periodStart: collected.periodStart, periodEnd: collected.periodEnd, title: content.title.trim(),
  summary: content.summary.trim(), body: content.body.trim(), category: 'Engineering', image: 'engineering', activities: collected.activities };
const bytes = encodeURIComponent(JSON.stringify(payload)).replace(/%[A-F\d]{2}/gi, 'U').length;
if (bytes > 1024 * 1024) throw new Error('Post and evidence exceed the 1 MiB website limit.');
return [{ json: { payload, publishEnabled: collected.publishEnabled, evidenceCount: collected.evidenceCount,
  publishUrl: collected.websiteUrl + '/api/updates' } }];
